<?php
namespace App\Livewire;
use App\Models\SchoolSetting;use Illuminate\Support\Facades\Auth;use Livewire\Attributes\Layout;use Livewire\Component;
#[Layout('layouts.app')] class ReportSettings extends Component {public string $level='primary',$passMark='50',$bestSubjects='8',$showPosition='enabled',$showFees='enabled',$showAttendance='enabled',$showPromotion='disabled',$footer='';public function mount():void{$v=SchoolSetting::where('school_id',Auth::user()->school_id)->pluck('value','key');$this->level=$v['report_level']??'primary';$this->passMark=$v['report_pass_mark']??'50';$this->bestSubjects=$v['report_secondary_best']??'8';$this->showPosition=$v['report_show_position']??'enabled';$this->showFees=$v['report_show_fees']??'enabled';$this->showAttendance=$v['report_show_attendance']??'enabled';$this->showPromotion=$v['report_show_promotion']??'disabled';$this->footer=$v['report_footer']??'';}public function save():void{$this->validate(['level'=>'required|in:primary,secondary','passMark'=>'required|numeric|min:0|max:100','bestSubjects'=>'required|integer|min:1|max:20','footer'=>'nullable|string|max:1000']);foreach(['report_level'=>$this->level,'report_pass_mark'=>$this->passMark,'report_secondary_best'=>$this->bestSubjects,'report_show_position'=>$this->showPosition,'report_show_fees'=>$this->showFees,'report_show_attendance'=>$this->showAttendance,'report_show_promotion'=>$this->showPromotion,'report_footer'=>$this->footer] as $key=>$value)SchoolSetting::updateOrCreate(['school_id'=>Auth::user()->school_id,'key'=>$key],['value'=>$value]);session()->flash('status','Report settings saved.');}public function render(){return view('livewire.report-settings',['pageTitle'=>'Report Settings']);}}
